mapper.select:
SELECT id, project_id AS projectId, title, description,
priority, status, deadline, creator_id AS creatorId,
assignee_id AS assigneeId, create_time AS createTime, update_time AS updateTime
FROM task
WHERE project_id = #{projectId}


    AND status = #{status}



    AND priority = #{priority}


ORDER BY create_time DESC

mapper.update:
UPDATE task
SET assignee_id = #{assigneeId}, update_time = NOW()
WHERE id = #{id}
